import type { Collection, Entry } from '../../engine/types'

/**
 * The SRD 5.2 spell list.
 *
 * Transcribed from the spell chapter of SRD 5.2 by a parser, not by hand and
 * not from memory — 339 spells, every field lifted from the document. The
 * scraper is in `tools/` so the transcription can be re-run and re-checked.
 *
 * This is a separate list from the 5.1 one rather than a shared import. The
 * editions genuinely differ here: 2024 adds spells (Starry Wisp, Sorcerous
 * Burst, True Strike is a different spell entirely), removes others, moves some
 * between schools — Acid Splash is Evocation now, not Conjuration — and rewrites
 * a great many effects.
 *
 * Tuple order: name, level, school, classes, casting time, range, components,
 * duration, effect. Classes use single letters:
 *   b bard · c cleric · d druid · p paladin · r ranger · s sorcerer
 *   k warlock · w wizard
 *
 * **On the two places the document disagrees with itself.** SRD 5.2 states each
 * class's list twice — once as a table in the class chapter, once in the
 * parenthetical on each spell's own entry — and in two cases they differ:
 *
 * - *Phantasmal Force* names Bard, Sorcerer and Wizard, but appears in none of
 *   those three class tables.
 * - *Mind Spike* names Sorcerer, Warlock and Wizard, but is absent from the
 *   Sorcerer table.
 *
 * Both discrepancies are present in two independent transcriptions of the
 * document, so they are the SRD's, not a scraping artefact. This module follows
 * the spell entries, on the grounds that a spell's own entry defines it and the
 * class tables are an index of those entries. `ruleset.test.ts` pins both cases
 * so the choice stays visible rather than becoming folklore.
 */

type SpellTuple = [
  name: string,
  level: number,
  school: string,
  classes: string,
  time: string,
  range: string,
  components: string,
  duration: string,
  text: string,
]

const CLASS_BY_LETTER: Record<string, string> = {
  b: 'bard',
  c: 'cleric',
  d: 'druid',
  p: 'paladin',
  r: 'ranger',
  s: 'sorcerer',
  k: 'warlock',
  w: 'wizard',
}

const SCHOOLS: Record<string, string> = {
  A: 'Abjuration',
  C: 'Conjuration',
  D: 'Divination',
  E: 'Enchantment',
  V: 'Evocation',
  I: 'Illusion',
  N: 'Necromancy',
  T: 'Transmutation',
}

