function slugify(name: string): string {
  return name
    .toLowerCase()
    .replace(/[’']/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
}

const entries: Entry[] = spells.map(([name, level, school, classes, time, range, components, duration, text]) => {
  const classList = classes.split('').map((letter) => CLASS_BY_LETTER[letter]).filter((value): value is string => !!value)
  const schoolName = SCHOOLS[school] ?? school
  const concentration = duration.startsWith('Concentration')
  const ritual = time.includes('Ritual')

  return {
    id: slugify(name),
    name,
    summary: text,
    icon: level === 0 ? '✨' : undefined,
    tags: [
      ...classList,
      `level-${level}`,
      schoolName.toLowerCase(),
      ...(concentration ? ['concentration'] : []),
      ...(ritual ? ['ritual'] : []),
    ],
    meta: {
      level,
      School: schoolName,
      'Casting Time': time,
      Range: range,
      Components: components,
      Duration: duration,
    },
  }
})

export const spellCollection: Collection = {
  id: 'spells',
  label: 'Spells',
  singular: 'Spell',
  entries,
}
